## Implementación

Todo con `std`: parser CSV incremental sobre `BufRead` (soporta comillas, comas y saltos de línea embebidos, `""` escapado, CRLF y BOM), suma compensada de Neumaier para no perder precisión sobre decenas de millones de filas, y un único buffer de registro reutilizado — la memoria no depende del tamaño del archivo.

```rust
//! Promedio de una columna numérica de un CSV en streaming. Solo std.

use std::fmt;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

// ---------------------------------------------------------------- API pública

/// Cómo ubicar la columna a promediar.
#[derive(Debug, Clone, Copy)]
pub enum Column<'a> {
    /// Índice 0-based, de izquierda a derecha.
    Index(usize),
    /// Nombre exacto del encabezado (exige `has_header = true`).
    Name(&'a str),
}

/// Resultado del cálculo.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Summary {
    /// Cantidad de valores numéricos válidos.
    pub count: u64,
    /// Campos vacíos encontrados en la columna (no entran al promedio).
    pub skipped: u64,
    /// Suma compensada.
    pub sum: f64,
    pub mean: f64,
}

#[derive(Debug)]
pub enum CsvError {
    Io(io::Error),
    /// Se pidió columna por nombre pero el CSV no tiene encabezado.
    HeaderRequired,
    HeaderNotFound(String),
    /// No hay ningún valor numérico que promediar.
    Empty,
    MissingColumn { record: u64, column: usize },
    InvalidUtf8 { record: u64, column: usize },
    NotNumeric { record: u64, column: usize, value: String },
}

impl fmt::Display for CsvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CsvError::Io(e) => write!(f, "error de E/S: {e}"),
            CsvError::HeaderRequired => {
                write!(f, "columna pedida por nombre pero has_header = false")
            }
            CsvError::HeaderNotFound(n) => write!(f, "no existe la columna {n:?}"),
            CsvError::Empty => write!(f, "no hay valores numéricos para promediar"),
            CsvError::MissingColumn { record, column } => {
                write!(f, "registro {record}: no existe la columna {column}")
            }
            CsvError::InvalidUtf8 { record, column } => {
                write!(f, "registro {record}, columna {column}: bytes no UTF-8")
            }
            CsvError::NotNumeric { record, column, value } => {
                write!(f, "registro {record}, columna {column}: {value:?} no es un número")
            }
        }
    }
}

impl std::error::Error for CsvError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            CsvError::Io(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for CsvError {
    fn from(e: io::Error) -> Self {
        CsvError::Io(e)
    }
}

