static DWORD WINAPI relay_sock_to_pipe(LPVOID p) {
    Relay *a = (Relay *)p;
    char buf[8192];
    for (;;) {
        int n = recv(a->sock, buf, sizeof(buf), 0);
        if (n <= 0) break;
        DWORD written = 0;
        if (!WriteFile(a->pipe, buf, (DWORD)n, &written, NULL) || written == 0) break;
    }
    CloseHandle(a->pipe);          /* propietario único: cierra su extremo */
    return 0;
}

