use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

const QUOTE: u8 = b'"';

#[derive(Debug, Clone)]
pub struct AverageConfig {
    /// Índice de columna, base 0.
    pub column: usize,
    /// Delimitador de campo (`,` por defecto, `;` en muchos CSV europeos).
    pub delimiter: u8,
    /// Si es `true`, se descarta el primer registro no vacío.
    pub has_header: bool,
}

impl Default for AverageConfig {
    fn default() -> Self {
        Self { column: 0, delimiter: b',', has_header: true }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct AverageResult {
    /// Filas cuyo campo se parseó como número finito.
    pub count: u64,
    /// Suma compensada (Kahan) de esos valores.
    pub sum: f64,
    /// Promedio; `f64::NAN` si `count == 0`.
    pub mean: f64,
    /// Filas descartadas: campo vacío, no numérico, `NaN`/`inf`, o fila corta.
    pub skipped: u64,
}

/// Conveniencia: abre el archivo y llama a `average_column`.
pub fn average_column_from_path<P: AsRef<Path>>(
    path: P,
    cfg: &AverageConfig,
) -> io::Result<AverageResult> {
    let file = File::open(path)?;
    // 1 MiB de buffer: reduce syscalls sin inflar la memoria residente.
    let reader = BufReader::with_capacity(1 << 20, file);
    average_column(reader, cfg)
}

/// Recorre el CSV registro a registro. Memoria usada: O(fila + 1 MiB), independiente
/// del tamaño del archivo.
pub fn average_column<R: BufRead>(mut reader: R, cfg: &AverageConfig) -> io::Result<AverageResult> {
    let mut record = Vec::with_capacity(512);
    let mut field = Vec::with_capacity(64);

    let mut sum = 0.0f64;
    let mut comp = 0.0f64; // compensación de Kahan
    let mut count = 0u64;
    let mut skipped = 0u64;

    let mut header_pending = cfg.has_header;
    let mut first_record = true;

    while read_raw_record(&mut reader, &mut record)? {
        if first_record {
            first_record = false;
            // BOM UTF-8 al inicio del archivo
            if record.starts_with(&[0xEF, 0xBB, 0xBF]) {
                record.drain(..3);
            }
        }
        if record.is_empty() {
            continue; // línea en blanco
        }
        if header_pending {
            header_pending = false;
            continue;
        }

        // Extrae sólo la columna pedida; no materializa el resto de la fila.
        let mut fields = Fields::new(&record, cfg.delimiter);
        let mut idx = 0usize;
        let mut found = false;
        while fields.next_field(&mut field).is_some() {
            if idx == cfg.column {
                found = true;
                break;
            }
            idx += 1;
        }

        if !found {
            skipped += 1; // fila más corta que la columna pedida
            continue;
        }

        let cell = trim_ascii(&field);
        if cell.is_empty() {
            skipped += 1;
            continue;
        }
        let parsed = std::str::from_utf8(cell)
            .ok()
            .and_then(|s| s.parse::<f64>().ok());
        match parsed {
            Some(v) if v.is_finite() => {
                // Kahan: evita la deriva de sumar decenas de millones de f64.
                let y = v - comp;
                let t = sum + y;
                comp = (t - sum) - y;
                sum = t;
                count += 1;
            }
            _ => skipped += 1,
        }
    }

    Ok(AverageResult {
        count,
        sum,
        mean: if count > 0 { sum / count as f64 } else { f64::NAN },
        skipped,
    })
}

