	v = strings.ToLower(strings.TrimSpace(v))
	if v == "" {
		return us
	}
	out := make([]Usuario, 0, len(us))
	for _, u := range us {
		if strings.ToLower(strings.TrimSpace(u.Nombre)) == v {
			out = append(out, u)
		}
