/** Lee un JSONL completo bajo lock compartido. */
function campaign_rows(string $file): array
{
    $path = campaign_config()['data_dir'] . '/' . $file;
    if (!is_file($path)) {
        return [];
    }
    $rows = [];
    $fh = fopen($path, 'rb');
    if (!$fh) {
        return [];
    }
    if (flock($fh, LOCK_SH)) {
        while (($line = fgets($fh)) !== false) {
            $line = trim($line);
            if ($line === '') {
                continue;
            }
            $row = json_decode($line, true);
            if (is_array($row)) {
                $rows[] = $row;
            }
        }
        flock($fh, LOCK_UN);
    }
    fclose($fh);
    return $rows;
}

/** Append atómico, permisos 0600. */
function campaign_append(string $file, array $row): void
{
    $path = campaign_config()['data_dir'] . '/' . $file;
    $fh = fopen($path, 'ab');
    if (!$fh) {
        return;
    }
    if (flock($fh, LOCK_EX)) {
        $json = json_encode($row, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        fwrite($fh, $json . "\n");
        fflush($fh);
        flock($fh, LOCK_UN);
    }
    fclose($fh);
    @chmod($path, 0600);
}

