struct Vec2 {
    float x = 0.f, y = 0.f;
    Vec2() = default;
    Vec2(float x, float y) : x(x), y(y) {}
};

struct Vec3 {
    float x = 0.f, y = 0.f, z = 0.f;
    Vec3() = default;
    Vec3(float x, float y, float z) : x(x), y(y), z(z) {}

    Vec3 operator+(const Vec3& o) const { return { x + o.x, y + o.y, z + o.z }; }
    Vec3 operator-(const Vec3& o) const { return { x - o.x, y - o.y, z - o.z }; }
    Vec3 operator*(float s)   const { return { x * s, y * s, z * s }; }
    Vec3& operator+=(const Vec3& o) { x += o.x; y += o.y; z += o.z; return *this; }

    float dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    float length()           const { return std::sqrt(x * x + y * y + z * z); }
    float distance(const Vec3& o) const { return (*this - o).length(); }
};

struct Matrix4x4 {
    float m[4][4]{};
};

// Transformación estándar de matriz de vista 4x4 (row-major, uso tipo Source/Havok).
// Si el juego almacena la matriz transpuesta, intercambiar m[r][c] <-> m[c][r].
inline bool WorldToScreen(const Vec3& pos, Vec2& out,
                          const Matrix4x4& vm, int width, int height)
{
    const float clipX = pos.x * vm.m[0][0] + pos.y * vm.m[1][0] + pos.z * vm.m[2][0] + vm.m[3][0];
    const float clipY = pos.x * vm.m[0][1] + pos.y * vm.m[1][1] + pos.z * vm.m[2][1] + vm.m[3][1];
    const float clipW = pos.x * vm.m[0][3] + pos.y * vm.m[1][3] + pos.z * vm.m[2][3] + vm.m[3][3];

    if (clipW < 0.001f)
        return false;

    const float ndcX = clipX / clipW;
    const float ndcY = clipY / clipW;

    out.x = (width  * 0.5f) * (1.f + ndcX);
    out.y = (height * 0.5f) * (1.f - ndcY);
    return true;
}
