# `promedio_csv.rs`

Máquina de estados byte a byte sobre `BufRead`, sin cargar el archivo en memoria y sin asignar por campo (solo se materializa la columna objetivo en un `Vec<u8>` reutilizado).

```rust
//! Promedio de una columna numérica de un CSV grande, en streaming y sin dependencias.
//!
//! - Memoria O(ancho de una fila) + O(1) de estado; nunca se carga el archivo entero.
//! - Soporta campos entrecomillados (`"..."` con `""` como escape), comas y saltos de
//!   línea embebidos, CRLF y BOM UTF-8.
//! - La columna se resuelve por índice o por nombre de encabezado.
//! - Suma con compensación de Kahan para no acumular error en archivos de GB.

use std::fmt;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// Buffer de lectura. 1 MiB amortiza bien syscalls en disco y SSD.
const BUF_SIZE: usize = 1 << 20;

// ---------------------------------------------------------------------------
// API pública
// ---------------------------------------------------------------------------

#[derive(Debug)]
pub enum CsvError {
    Io(io::Error),
    ColumnNotFound(String),
    RowTooShort { record: u64, column: usize, fields: usize },
    InvalidNumber { record: u64, column: usize, value: String },
    NoNumericValues,
    InvalidConfig(String),
}

impl fmt::Display for CsvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CsvError::Io(e) => write!(f, "error de E/S: {e}"),
            CsvError::ColumnNotFound(n) => {
                write!(f, "no se encontró la columna \"{n}\" en el encabezado")
            }
            CsvError::RowTooShort { record, column, fields } => write!(
                f,
                "registro {record}: la columna {column} no existe (la fila tiene {fields} campos)"
            ),
            CsvError::InvalidNumber { record, column, value } => write!(
                f,
                "registro {record}, columna {column}: valor no numérico {value:?}"
            ),
            CsvError::NoNumericValues => write!(f, "no hay valores numéricos en la columna"),
            CsvError::InvalidConfig(m) => write!(f, "configuración inválida: {m}"),
        }
    }
}

impl std::error::Error for CsvError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            CsvError::Io(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for CsvError {
    fn from(e: io::Error) -> Self {
        CsvError::Io(e)
    }
}

/// Qué hacer cuando una fila no aporta un número válido.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InvalidPolicy {
    /// Cuenta la fila en `skipped` y sigue.
    Skip,
    /// Corta con `CsvError::InvalidNumber` / `CsvError::RowTooShort`.
    Fail,
}

#[derive(Debug, Clone)]
pub enum Column {
    Index(usize),
    Name(String),
}

#[derive(Debug, Clone)]
pub struct Config {
    pub column: Column,
    pub has_header: bool,
    pub on_invalid: InvalidPolicy,
}

impl Config {
    pub fn by_index(i: usize) -> Self {
        Config {
            column: Column::Index(i),
            has_header: true,
            on_invalid: InvalidPolicy::Skip,
        }
    }

    pub fn by_name(name: impl Into<String>) -> Self {
        Config {
            column: Column::Name(name.into()),
            has_header: true,
            on_invalid: InvalidPolicy::Skip,
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Mean {
    pub mean: f64,
    /// Filas que aportaron un valor a la media.
    pub count: u64,
    /// Filas descartadas (vacías, no numéricas o con la columna ausente).
    pub skipped: u64,
}

/// Punto de entrada para archivos en disco.
pub fn mean_of_numeric_column_in_file(
    path: impl AsRef<Path>,
    config: &Config,
) -> Result<Mean, CsvError> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(BUF_SIZE, file);
    mean_of_numeric_column(reader, config)
