#pragma once
#include <cmath>

struct Vec2 { float x = 0.f, y = 0.f; };

struct Vec3 {
    float x = 0.f, y = 0.f, z = 0.f;

    Vec3 operator+(const Vec3& o) const { return { x + o.x, y + o.y, z + o.z }; }
    Vec3 operator-(const Vec3& o) const { return { x - o.x, y - o.y, z - o.z }; }
    Vec3 operator*(float s)      const { return { x * s,  y * s,  z * s  }; }
    float Length()               const { return std::sqrt(x * x + y * y + z * z); }
    float Length2D()             const { return std::sqrt(x * x + y * y); }
};

// Engine view matrix: 4x4 float, row-major as stored in memory
// (row i occupies m[i*4 .. i*4+3]).
struct ViewMatrix { float m[16]{ }; };

// Standard perspective divide against a row-major view-projection matrix.
// Returns false if the point is behind the camera plane.
inline bool WorldToScreen(const Vec3& world, Vec2& out, const float* m,
                          float screenW, float screenH)
{
    const float w = m[3] * world.x + m[7] * world.y + m[11] * world.z + m[15];
    if (w < 0.001f)
        return false;

    const float x = m[0] * world.x + m[4] * world.y + m[8]  * world.z + m[12];
    const float y = m[1] * world.x + m[5] * world.y + m[9]  * world.z + m[13];

    const float invW = 1.0f / w;
    out.x = (screenW * 0.5f) * (1.0f + x * invW);
    out.y = (screenH * 0.5f) * (1.0f - y * invW);

    if (out.x < -screenW || out.x > screenW * 2.0f ||
        out.y < -screenH || out.y > screenH * 2.0f)
        return false;

    return true;
}
