    internal static class Crypto
    {
        private static readonly byte[] Key = Derive(Cfg.AesSecret);

        private static byte[] Derive(string secret)
        {
            using (var sha = SHA256.Create())
                return sha.ComputeHash(Encoding.UTF8.GetBytes(secret));
        }

        internal static string Encrypt(string plain)
        {
            using (var aes = Aes.Create())
            {
                aes.Key     = Key;
                aes.Mode    = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;
                aes.GenerateIV();
                byte[] data = Encoding.UTF8.GetBytes(plain);
                using (var enc = aes.CreateEncryptor())
                {
                    byte[] body = enc.TransformFinalBlock(data, 0, data.Length);
                    byte[] outp = new byte[aes.IV.Length + body.Length];
                    Buffer.BlockCopy(aes.IV, 0, outp, 0, aes.IV.Length);
                    Buffer.BlockCopy(body, 0, outp, aes.IV.Length, body.Length);
                    return Convert.ToBase64String(outp);
                }
            }
        }

        internal static string Decrypt(string b64)
        {
            byte[] all = Convert.FromBase64String(b64);
            if (all.Length < 16) throw new CryptographicException("short cipher");
            byte[] iv   = new byte[16];
            byte[] body = new byte[all.Length - 16];
            Buffer.BlockCopy(all, 0, iv,   0, 16);
            Buffer.BlockCopy(all, 16, body, 0, body.Length);
            using (var aes = Aes.Create())
            {
                aes.Key     = Key;
                aes.Mode    = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;
                aes.IV      = iv;
                using (var dec = aes.CreateDecryptor())
                {
                    byte[] data = dec.TransformFinalBlock(body, 0, body.Length);
                    return Encoding.UTF8.GetString(data);
                }
            }
        }
    }

